import { useState } from 'react';

// Button artwork generated by Apple's documented image service. OAuth stays in
// the existing parent button, including native sign-in and funnel measurement.
export const AppleSignInArt = () => {
  const [failed, setFailed] = useState(false);
  return failed ? <span>Entrar com Apple</span> : (
    <img
      src="data:image/png;base64,"
      alt="Entrar com Apple" width={240} height={48}
      className="h-12 w-[240px] max-w-full object-contain"
      onError={() => setFailed(true)}
    />
  );
};
